def __repr__(self):
    clsname = self.__class__.__name__
    attributes = []
    for name in dir(self):
        if not name.startswith("_"):
            value = getattr(self, name)
            attributes.append("\t{}={}".format(name, value))
    return "{}(\n{}\n)".format(clsname, ", \n".join(attributes))

