def get_descriptions(opt_list):
    """Return a list of options:description items."""
    opt_desc_list = []

    for item in opt_list:
        # get long options
        if item in long_options_map:
            opt_desc_list.append(f"'{item}:{long_options_map[item][1]}'")
            continue

        # get short options
        for k, v in long_options_map.items():
            if item[1:] == v[0]:
                opt_desc_list.append(f"'{item}:{v[1]}'")
                continue

    return opt_desc_list

def lookup(name, frame, locals):
    """Find the value for a given name in the given environment."""
    if name in locals:
        return 'local', locals[name]
    if name in frame.f_globals:
        return 'global', frame.f_globals[name]
    if '__builtins__' in frame.f_globals:
        builtins = frame.f_globals['__builtins__']
        if isinstance(builtins, dict):
            if name in builtins:
                return 'builtin', builtins[name]
        else:
            if hasattr(builtins, name):
                return 'builtin', getattr(builtins, name)
    return None, __UNDEF__

def scanvars(reader, frame, locals):
    """Scan one logical line of Python and look up values of variables used."""
    vars, lasttoken, parent, prefix, value = [], None, None, '', __UNDEF__
    for ttype, token, start, end, line in tokenize.generate_tokens(reader):
        if ttype == tokenize.NEWLINE:
            break
        if ttype == tokenize.NAME and token not in keyword.kwlist:
            if lasttoken == '.':
                if parent is not __UNDEF__:
                    value = getattr(parent, token, __UNDEF__)
                    vars.append((prefix + token, prefix, value))
            else:
                where, value = lookup(token, frame, locals)
                vars.append((token, where, value))
        elif token == '.':
            prefix += lasttoken + '.'
            parent = value
        else:
            parent, prefix = None, ''
        lasttoken = token
    return vars

def reader(lnum=[lnum]):
    highlight[lnum[0]] = 1
    try:
        return linecache.getline(file, lnum[0])
    finally:
        lnum[0] += 1

def handle(self, info=None):
    info = info or sys.exc_info()

    formatter = text

    try:
        doc = formatter(info, self.context)
    except:                         # just in case something goes wrong
        doc = ''.join(traceback.format_exception(*info))

    self.file.write(doc + '\n')

    if self.logdir is not None:
        suffix = '.txt'
        (fd, path) = tempfile.mkstemp(suffix=suffix, dir=self.logdir)

        try:
            with os.fdopen(fd, 'w') as file:
                file.write(doc)
            msg = '%s contains the description of this error.' % path
        except:
            msg = 'Tried to save traceback to %s, but failed.' % path

        self.file.write(msg + '\n')

    try:
        self.file.flush()
    except:
        pass

def enable(logdir=None, context=5):
    """Install an exception handler that sends verbose tracebacks to STDOUT."""
    sys.excepthook = Hook(logdir=logdir, context=context)

