def __iter__(self):
    end = self.__end
    curr = end[2]
    while curr is not end:
        yield curr[0]
        curr = curr[2]

def __reversed__(self):
    end = self.__end
    curr = end[1]
    while curr is not end:
        yield curr[0]
        curr = curr[1]

