def _parse_volume(next_lines: List[str]) -> Optional[Volume]:
    next_line = next_lines.pop()
    result = re.match(_volume_line_pattern, next_line)

    # Parse and return the volume given as a single line (veracrypt -t --list)
    if result:
        matches = result.groupdict()
        volume: Volume = {  # type: ignore
            "slot": int(matches["slot"]),
            "path": matches["path"],
            "device": matches["device"],
            "mountpoint": matches["mountpoint"],
        }

        return volume
    else:
        next_lines.append(next_line)

    # Otherwise parse the volume given in multiple lines (veracrypt -t --list -v)
    volume: Volume = {}  # type: ignore

    while next_lines:
        next_line = next_lines.pop()

        # Return when encounter an empty line
        if not next_line:
            return volume

        result = re.match(_volume_verbose_pattern, next_line)

        # Skip to the next line in case of an unknown field line
        if not result:
            continue

        matches = result.groupdict()

        if matches["slot"]:
            volume["slot"] = int(matches["slot"])
        elif matches["path"]:
            volume["path"] = matches["path"]
        elif matches["device"]:
            volume["device"] = matches["device"]
        elif matches["mountpoint"]:
            volume["mountpoint"] = matches["mountpoint"]
        elif matches["size"]:
            volume["size"] = matches["size"]
        elif matches["type"]:
            volume["type"] = matches["type"]
        elif matches["readonly"]:
            volume["readonly"] = matches["readonly"]
        elif matches["hidden_protected"]:
            volume["hidden_protected"] = matches["hidden_protected"]
        elif matches["encryption_algo"]:
            volume["encryption_algo"] = matches["encryption_algo"]
        elif matches["pk_size"]:
            volume["pk_size"] = matches["pk_size"]
        elif matches["sk_size"]:
            volume["sk_size"] = matches["sk_size"]
        elif matches["block_size"]:
            volume["block_size"] = matches["block_size"]
        elif matches["mode"]:
            volume["mode"] = matches["mode"]
        elif matches["prf"]:
            volume["prf"] = matches["prf"]
        elif matches["format_version"]:
            volume["format_version"] = int(matches["format_version"])
        elif matches["backup_header"]:
            volume["backup_header"] = matches["backup_header"]

    return volume

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema.
    """
    for entry in proc_data:

        # convert integers and booleans
        int_list = {'rssi'}
        bool_list = {'ht'}
        for key in entry:
            if key in int_list:
                entry[key] = jc.utils.convert_to_int(entry[key])
            if key in bool_list:
                entry[key] = jc.utils.convert_to_bool(entry[key])

        if 'security' in entry:
            entry['security'] = entry['security'].split()

    return proc_data

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema.
    """
    for entry in proc_data:
        if 'user' in entry and entry['user'] == 'boot_time':
            entry['user'] = 'boot time'

        if 'tty' in entry and entry['tty'] == '~':
            entry['tty'] = None

        if 'hostname' in entry and entry['hostname'] == '-':
            entry['hostname'] = None

        if 'hostname' in entry and entry['hostname'] is not None and entry['hostname'][0] == ":":
            entry['hostname'] = f'CONSOLE{entry["hostname"]}'

        if 'logout' in entry and entry['logout'] == 'still_logged_in':
            entry['logout'] = 'still logged in'

        if 'logout' in entry and entry['logout'] == 'gone_-_no_logout':
            entry['logout'] = 'gone - no logout'

        if 'login' in entry and LOGIN_LOGOUT_EPOCH_RE.match(entry['login']):
            timestamp = jc.utils.timestamp(entry['login'])
            entry['login_epoch'] = timestamp.naive

        if 'logout' in entry and LOGIN_LOGOUT_EPOCH_RE.match(entry['logout']):
            timestamp = jc.utils.timestamp(entry['logout'])
            entry['logout_epoch'] = timestamp.naive

        if 'login_epoch' in entry and 'logout_epoch' in entry:
            entry['duration_seconds'] = entry['logout_epoch'] - entry['login_epoch']

        if 'duration' in entry and re.match(r'^\d+\+', entry['duration']):
            m = re.match(r'^(?P<days>\d+)\+(?P<hours>\d\d):(?P<minutes>\d\d)', entry['duration'])
            days, hours, minutes = m.groups()
            entry['duration'] = f'{int(days)*24 + int(hours)}:{minutes}'

    return proc_data

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema:
    """
    desired_map = {
        'u': 'unknown',
        'i': 'install',
        'r': 'remove',
        'p': 'purge',
        'h': 'hold'
    }

    status_map = {
        'n': 'not installed',
        'i': 'installed',
        'c': 'config-files',
        'u': 'unpacked',
        'f': 'failed config',
        'h': 'half installed',
        'w': 'trigger await',
        't': 'trigger pending'
    }

    err_map = {
        'r': 'reinstall required'
    }

    for entry in proc_data:
        if 'codes' in entry:
            desired, status, *err = list(entry['codes'].lower())

            if desired in desired_map:
                entry['desired'] = desired_map[desired]

            if status in status_map:
                entry['status'] = status_map[status]

            if err and err[0] in err_map:
                entry['error'] = err_map[err[0]]

    return proc_data

def add_probe(self, probe):
    """Adds a Probe instance to this hop's results."""
    if self.probes:
        probe_last = self.probes[-1]
        if not probe.ip:
            probe.ip = probe_last.ip
            probe.name = probe_last.name
    self.probes.append(probe)

