def parse_post(raw_data):
    for entry in raw_data:
        # fixup name field in Registered kernel control module
        if 'name' in entry:
            if entry['name']:
                entry['name'] = entry['name'].strip()

        # create network and transport protocol fields
        if 'local_address' in entry:
            if entry['local_address']:
                ladd = entry['local_address'].rsplit('.', maxsplit=1)[0]
                lport = entry['local_address'].rsplit('.', maxsplit=1)[1]
                entry['local_address'] = ladd
                entry['local_port'] = lport

        if 'foreign_address' in entry:
            if entry['foreign_address']:
                fadd = entry['foreign_address'].rsplit('.', maxsplit=1)[0]
                fport = entry['foreign_address'].rsplit('.', maxsplit=1)[1]
                entry['foreign_address'] = fadd
                entry['foreign_port'] = fport

        if 'proto' in entry and 'kind' in entry:
            if entry['kind'] == 'network':
                if entry['proto'] == 'udp46':
                    entry['transport_protocol'] = entry['proto'][:-2]
                elif entry['proto'].startswith('icm'):
                    entry['transport_protocol'] = 'icmp'
                else:
                    entry['transport_protocol'] = entry['proto'][:-1]

                if '6' in entry['proto']:
                    entry['network_protocol'] = 'ipv6'
                else:
                    entry['network_protocol'] = 'ipv4'

        # add route_flags_pretty field
        if 'route_flags' in entry:
            flag_map = {
                '1': 'PROTO1',
                '2': 'PROTO2',
                '3': 'PROTO3',
                'B': 'BLACKHOLE',
                'b': 'BROADCAST',
                'C': 'CLONING',
                'c': 'PRCLONING',
                'D': 'DYNAMIC',
                'G': 'GATEWAY',
                'H': 'HOST',
                'I': 'IFSCOPE',
                'i': 'IFREF',
                'L': 'LLINFO',
                'M': 'MODIFIED',
                'm': 'MULTICAST',
                'R': 'REJECT',
                'r': 'ROUTER',
                'S': 'STATIC',
                'U': 'UP',
                'W': 'WASCLONED',
                'X': 'XRESOLVE',
                'Y': 'PROXY',
            }

            pretty_flags = []

            for flag in entry['route_flags']:
                if flag in flag_map:
                    pretty_flags.append(flag_map[flag])

            entry['route_flags_pretty'] = pretty_flags

        # strip whitespace from beginning and end of all string values
        for item in entry:
            if isinstance(entry[item], str):
                entry[item] = entry[item].strip()

    return raw_data

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema.
    """
    for entry in proc_data:
        # time conversions
        if 'updated' in entry:
            updated_list = entry['updated'].replace('(', '').replace(')', '').split()
            entry['updated'] = ' '.join(updated_list[:-3])
            entry['updated_seconds_ago'] = jc.utils.convert_to_int(updated_list[-3])

            if entry['updated']:
                hints = (1000, 2000, 3000, 4000, 5000, 8000, 8100)
                ts = jc.utils.timestamp(entry['updated'], format_hint=hints)
                entry['updated_epoch'] = ts.naive
                entry['updated_epoch_utc'] = ts.utc

        # top level boolean conversions
        bool_list = [
            'power_supply', 'has_history', 'has_statistics', 'on_battery', 'lid_is_closed',
            'lid_is_present'
        ]
        for key in entry:
            if key in bool_list:
                entry[key] = jc.utils.convert_to_bool(entry[key])

        # detail level boolean conversions
        bool_list = ['online', 'present', 'rechargeable']
        if 'detail' in entry:
            for key in entry['detail']:
                if key in bool_list:
                    entry['detail'][key] = jc.utils.convert_to_bool(entry['detail'][key])

        # detail level convert warning to null if value is none
        if 'detail' in entry:
            if 'warning_level' in entry['detail']:
                if entry['detail']['warning_level'] == 'none':
                    entry['detail']['warning_level'] = None

        # detail level convert energy readings to float and add unit keys
        if 'detail' in entry:
            add_items = []
            for key, value in entry['detail'].items():
                if value and isinstance(value, str):
                    if len(value.split()) == 2:
                        entry['detail'][key] = jc.utils.convert_to_float(value.split()[0])
                        add_items.append({
                            key + '_unit': value.split()[1]
                        })

            if add_items:
                for item in add_items:
                    for key, value in item.items():
                        entry['detail'][key] = value

        # detail level fix percentages
        if 'detail' in entry:
            for key, value in entry['detail'].items():
                if value and isinstance(value, str):
                    if value[-1] == '%':
                        entry['detail'][key] = jc.utils.convert_to_float(value)

        # detail level fix quoted values
        if 'detail' in entry:
            for key, value in entry['detail'].items():
                if value and isinstance(value, str):
                    if value.startswith("'") and value.endswith("'"):
                        entry['detail'][key] = value[1:-1]

        # history_charge and history_rate level convert floats and ints
        histories = []

        if 'history_charge' in entry:
            histories.append('history_charge')
        if 'history_rate' in entry:
            histories.append('history_rate')

        if histories:
            for history_obj_list in histories:
                new_history_list = []
                for history_obj in entry[history_obj_list]:
                    new_history_obj = {}
                    for key, value in history_obj.items():
                        if key == 'time':
                            new_history_obj[key] = jc.utils.convert_to_int(value)
                        elif key == 'percent_charged':
                            new_history_obj[key] = jc.utils.convert_to_float(value)
                        else:
                            new_history_obj[key] = value

                    new_history_list.append(new_history_obj)

                entry[history_obj_list] = new_history_list

    return proc_data

def parse(data, raw=False, quiet=False):
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output = []
    device_obj = {}
    device_name = None
    history_key = ''
    history_list = []
    history_list_obj = {}

    if jc.utils.has_data(data):

        for line in filter(None, data.splitlines()):
            if line.startswith('Device:') or line.startswith('Daemon:'):
                if device_obj:
                    raw_output.append(device_obj)
                    device_obj = {}

                if line.startswith('Device:'):
                    device_name = line.split(':', maxsplit=1)[1].strip()
                    device_obj = {
                        'type': 'Device',
                        "device_name": device_name
                    }

                elif line.startswith('Daemon:'):
                    device_obj = {
                        'type': 'Daemon'
                    }

                continue

            # history detail lines
            if line.startswith('    ') and ':' not in line:
                line_list = line.strip().split()
                history_list_obj = {
                    'time': line_list[0],
                    'percent_charged': line_list[1],
                    'status': line_list[2]
                }
                history_list.append(history_list_obj)
                device_obj[history_key] = history_list
                continue

            # general detail lines
            if line.startswith('    ') and ':' in line:
                key = line.split(':', maxsplit=1)[0].strip().lower().replace('-', '_')\
                                                    .replace(' ', '_').replace('(', '')\
                                                    .replace(')', '')
                val = line.split(':', maxsplit=1)[1].strip()
                device_obj['detail'][key] = val
                continue

            # history detail lines are a special case of detail lines
            # set the history detail key
            if line.startswith('  History (charge):') or line.startswith('  History (rate):'):
                if line.startswith('  History (charge):'):
                    history_key = 'history_charge'
                elif line.startswith('  History (rate):'):
                    history_key = 'history_rate'

                device_obj[history_key] = {}
                history_list = []
                continue

            # top level lines
            if line.startswith('  ') and ':' in line:
                key = line.split(':', maxsplit=1)[0].strip().lower().replace('-', '_')\
                                                    .replace(' ', '_').replace('(', '')\
                                                    .replace(')', '')
                val = line.split(':', maxsplit=1)[1].strip()
                device_obj[key] = val
                continue

            # set the general detail object
            if line.startswith('  ') and ':' not in line:
                detail_type = line.strip()
                device_obj['detail'] = {
                    'type': detail_type
                }
                continue

    if device_obj:
        raw_output.append(device_obj)

    if raw:
        return raw_output
    else:
        return _process(raw_output)

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (Dictionary) raw structured data to process

    Returns:

        Dictionary. Structured data to conform to the schema.
    """
    int_list = {
        'data_bytes', 'packets_transmitted', 'packets_received', 'bytes', 'icmp_seq', 'ttl',
        'duplicates', 'corrupted', 'errors', 'vr', 'hl', 'tos', 'len', 'id', 'flg', 'off', 'pro', 'cks'
    }

    float_list = {
        'packet_loss_percent', 'round_trip_ms_min', 'round_trip_ms_avg', 'round_trip_ms_max',
        'round_trip_ms_stddev', 'timestamp', 'time_ms'
    }

    for key in proc_data:
        if key in int_list:
            proc_data[key] = jc.utils.convert_to_int(proc_data[key])

        if key in float_list:
            proc_data[key] = jc.utils.convert_to_float(proc_data[key])

        if key == 'responses':
            for entry in proc_data['responses']:
                for k in entry:
                    if k in int_list:
                        entry[k] = jc.utils.convert_to_int(entry[k])

                    if k in float_list:
                        entry[k] = jc.utils.convert_to_float(entry[k])

    return proc_data

def _linux_parse(data):
    raw_output = {}
    ping_responses = []
    pattern = None
    footer = False

    linedata = data.splitlines()

    # check for PATTERN
    if linedata[0].startswith('PATTERN: '):
        pattern = linedata.pop(0).split(': ')[1]

    while not linedata[0].startswith('PING '):
        linedata.pop(0)

    ipv4 = True if 'bytes of data' in linedata[0] else False

    if ipv4 and linedata[0][5] not in string.digits:
        hostname = True
        # fixup for missing hostname
        linedata[0] = linedata[0][:5] + 'nohost' + linedata[0][5:]
    elif ipv4 and linedata[0][5] in string.digits:
        hostname = False
    elif not ipv4 and ' (' in linedata[0]:
        hostname = True
    else:
        hostname = False

    for line in filter(None, linedata):
        if line.startswith('PING '):
            if ipv4 and not hostname:
                dst_ip, dta_byts = (2, 3)
            elif ipv4 and hostname:
                dst_ip, dta_byts = (2, 3)
            elif not ipv4 and not hostname:
                dst_ip, dta_byts = (2, 3)
            else:
                dst_ip, dta_byts = (3, 4)

            line = line.replace('(', ' ').replace(')', ' ')
            raw_output.update(
                {
                    'destination_ip': line.split()[dst_ip].lstrip('(').rstrip(')'),
                    'data_bytes': line.split()[dta_byts],
                    'pattern': pattern
                }
            )
            continue

        if line.startswith('---'):
            footer = True
            if line[4] != ' ':  # fixup for missing hostname
                raw_output['destination'] = line.split()[1]
            continue

        if footer:
            # Init in zero, to keep compatibility with previous behaviour
            if 'duplicates' not in raw_output:
                raw_output['duplicates'] = '0'

            #
            # See: https://github.com/dgibson/iputils/blob/master/ping_common.c#L995
            #
            m = re.search(r'(\d+) packets transmitted', line)
            if m:
                raw_output['packets_transmitted'] = m.group(1)

            m = re.search(r'(\d+) received,', line)
            if m:
                raw_output['packets_received'] = m.group(1)

            m = re.search(r'[+](\d+) duplicates', line)
            if m:
                raw_output['duplicates'] = m.group(1)

            m = re.search(r'[+](\d+) corrupted', line)
            if m:
                raw_output['corrupted'] = m.group(1)

            m = re.search(r'[+](\d+) errors', line)
            if m:
                raw_output['errors'] = m.group(1)

            m = re.search(r'([\d\.]+)% packet loss', line)
            if m:
                raw_output['packet_loss_percent'] = m.group(1)

            m = re.search(r'time (\d+)ms', line)
            if m:
                raw_output['time_ms'] = m.group(1)

            m = re.search(r'rtt min\/avg\/max\/mdev += +([\d\.]+)\/([\d\.]+)\/([\d\.]+)\/([\d\.]+) ms', line)
            if m:
                raw_output['round_trip_ms_min'] = m.group(1)
                raw_output['round_trip_ms_avg'] = m.group(2)
                raw_output['round_trip_ms_max'] = m.group(3)
                raw_output['round_trip_ms_stddev'] = m.group(4)

        # ping response lines
        else:
            # request timeout
            if 'no answer yet for icmp_seq=' in line:
                timestamp = False
                isequence = 5

                # if timestamp option is specified, then shift icmp sequence field right by one
                if line[0] == '[':
                    timestamp = True
                    isequence = 6

                response = {
                    'type': 'timeout',
                    'timestamp': line.split()[0].lstrip('[').rstrip(']') if timestamp else None,
                    'icmp_seq': line.replace('=', ' ').split()[isequence]
                }
                ping_responses.append(response)
                continue

            # normal responses
            elif ' bytes from ' in line:
                try:
                    line = line.replace('(', ' ').replace(')', ' ').replace('=', ' ')

                    # positions of items depend on whether ipv4/ipv6 and/or ip/hostname is used
                    if ipv4 and not hostname:
                        bts, rip, iseq, t2l, tms = (0, 3, 5, 7, 9)
                    elif ipv4 and hostname:
                        bts, rip, iseq, t2l, tms = (0, 4, 7, 9, 11)
                    elif not ipv4 and not hostname:
                        bts, rip, iseq, t2l, tms = (0, 3, 5, 7, 9)
                    elif not ipv4 and hostname:
                        bts, rip, iseq, t2l, tms = (0, 4, 7, 9, 11)

                    # if timestamp option is specified, then shift everything right by one
                    timestamp = False
                    if line[0] == '[':
                        timestamp = True
                        bts, rip, iseq, t2l, tms = (bts + 1, rip + 1, iseq + 1, t2l + 1, tms + 1)

                    response = {
                        'type': 'reply',
                        'timestamp': line.split()[0].lstrip('[').rstrip(']') if timestamp else None,
                        'bytes': line.split()[bts],
                        'response_ip': line.split()[rip].rstrip(':'),
                        'icmp_seq': line.split()[iseq],
                        'ttl': line.split()[t2l],
                        'time_ms': line.split()[tms],
                        'duplicate': True if 'DUP!' in line else False
                    }
                except Exception:
                    response = {
                        'type': 'unparsable_line',
                        'unparsed_line': line
                    }

                ping_responses.append(response)
                continue

    raw_output['responses'] = ping_responses

    return raw_output

def parse(data, raw=False, quiet=False):
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        Dictionary. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output = {}

    if jc.utils.has_data(data):

        if ' time ' in data.splitlines()[-2] or ' time ' in data.splitlines()[-3]:
            raw_output = _linux_parse(data)
        else:
            raw_output = _bsd_parse(data)

    if raw:
        return raw_output
    else:
        return _process(raw_output)

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema.
    """
    for entry in proc_data:
        int_list = {'size', 'blocks', 'io_blocks', 'inode', 'links', 'uid', 'gid',
                    'unix_device', 'rdev', 'block_size'}

        null_list = {'access_time', 'modify_time', 'change_time', 'birth_time'}

        for key in entry.copy():
            if key in int_list:
                entry[key] = jc.utils.convert_to_int(entry[key])

            # turn - into null for time fields and add calculated timestamp fields
            if key in null_list:
                if entry[key] == '-':
                    entry[key] = None
                ts = jc.utils.timestamp(entry[key], format_hint=(7100, 7200))
                entry[key + '_epoch'] = ts.naive
                entry[key + '_epoch_utc'] = ts.utc

    return proc_data

def _process(proc_data: List[Dict]) -> List[Dict]:
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema:
    """
    int_list = {'expires'}

    # in BSD style, change name to null if it is a question mark
    for entry in proc_data:
        if 'name' in entry and entry['name'] == '?':
            entry['name'] = None

        for key in entry:
            if key in int_list:
                entry[key] = jc.utils.convert_to_int(entry[key])

    return proc_data

def _process(proc_data):
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured data to conform to the schema.
    """
    int_list = {
        'part_entry_number', 'part_entry_offset', 'part_entry_size', 'id_part_entry_number',
        'id_part_entry_offset', 'id_part_entry_size', 'minimum_io_size', 'physical_sector_size',
        'logical_sector_size', 'id_iolimit_minimum_io_size', 'id_iolimit_physical_sector_size',
        'id_iolimit_logical_sector_size'
    }

    for entry in proc_data:
        if 'devname' in entry:
            entry['device'] = entry.pop('devname')

        for key in entry:
            if key in int_list:
                entry[key] = jc.utils.convert_to_int(entry[key])

    return proc_data

def parse(data, raw=False, quiet=False):
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output = []

    if jc.utils.has_data(data):

        # if the first field is a device, use normal parsing:
        if data.split(maxsplit=1)[0][-1] == ':':
            linedata = data.splitlines()

            for line in linedata:
                output_line = {}
                entries = shlex.split(line)
                output_line['device'] = entries.pop(0)[:-1]

                for entry in entries:
                    key = entry.split('=', maxsplit=1)[0].lower()
                    value = entry.split('=', maxsplit=1)[1]
                    output_line[key] = value

                raw_output.append(output_line)

        # else use key/value per line parsing
        else:
            linedata = data.splitlines()
            output_line = {}
            for line in linedata:
                if line == '':
                    if output_line:
                        raw_output.append(output_line)
                        output_line = {}
                        continue
                    continue

                key = line.split('=', maxsplit=1)[0].lower()
                value = line.split('=', maxsplit=1)[1]
                output_line[key] = value

            if output_line:
                raw_output.append(output_line)

    if raw:
        return raw_output
    else:
        return _process(raw_output)

def IsOctalNumber(character):
    oct_digits = set(string.octdigits)
    return set(character).issubset(oct_digits)

def IsHexNumber(character):
    hex_digits = set(string.hexdigits)
    return set(character).issubset(hex_digits)

def LineNumberForIndex(string_data, current_index):
    line_number = 1
    index = 0
    string_length = len(string_data)
    while (index < current_index) and (index < string_length):
        current_char = string_data[index]
        if IsNewline(current_char) is True:
            line_number += 1
        index += 1
    return line_number

def IsValidUnquotedStringCharacter(character):
    if len(character) == 1:
        valid_characters = set(string.ascii_letters+string.digits+'_$/:.-')
        return set(character).issubset(valid_characters)
    else: # pragma: no cover
        message = 'The function "IsValidUnquotedStringCharacter()" can only take single characters!'
        raise ValueError(message)

def IsEndOfLine(character):
    result = (IsNewline(character) or IsUnicodeSeparator(character))
    return result

def StringCmp(obj1, obj2):
    result = -1
    if obj1 > obj2:
        result = 1
    elif obj1 == obj2:
        result = 0
    return result

def KeySorter(obj1, obj2):
    result = 0
    if str(obj1) == 'isa':
        result = -1
    elif str(obj2) == 'isa':
        result = 1
    else:
        result = StringCmp(str(obj1), str(obj2))
    return result

def sortedKeys(self):
    unsorted_keys = self.key_storage
    sorted_keys = sorted(unsorted_keys, key=cmp_to_key(KeySorter))
    can_sort = False
    if len(sorted_keys) > 0:
        all_dictionaries = all((isinstance(self[key].value, dict) or isinstance(self[key].value, pbRoot)) for key in unsorted_keys)
        if all_dictionaries:
            can_sort = all(self[key].get('isa', None) is not None for key in unsorted_keys)
            if can_sort:
                sorted_keys = sorted(unsorted_keys, key=lambda k: str(self[k]['isa']))
    return (can_sort, sorted_keys)

def __setitem__(self, key, value):
    if key not in self.key_storage:
        self.key_storage.append(self.__internalKeyCheck(key))
    self.store[key] = value

def __delitem__(self, key):
    if key in self.key_storage:
        self.key_storage.remove(key)
    del self.store[key]

def _setup(self):
    _map = self.__class__._map
    for other_cls in (EncryptionAlgorithmId, SignedDigestAlgorithmId, DigestAlgorithmId):
        for oid, name in other_cls._map.items():
            _map[oid] = name

def __iter__(self):
    """Return the match method once, then stop"""
    yield self.match

def __eq__(self, other):
    is_equal = False
    if isinstance(other, pbItem):
        other = other.value
    if type(other) is type(self.value):
        is_equal = self.value.__eq__(other)
    return is_equal

def __eq__(self, other):
    """
    :param other:
        Another IPAddress object

    :return:
        A boolean
    """

    if not isinstance(other, IPAddress):
        return False

    return self.__bytes__() == other.__bytes__()

def WriteIndent(level=0):
    output = ''
    for _index in range(level):
        output += '\t'
    return output

def WriteNewline(level=0, indent=True):
    output = '\n'
    if indent:
        output += WriteIndent(level)
    return output

def writeString(self, indent_level=0, pretty=True):
    dictionary_string = ''
    dictionary_string += '{'
    has_sorted_keys, keys_array = self.value.sortedKeys()
    dictionary_string += WriteNewline(indent_level, not has_sorted_keys)
    indent_level = PushIndent(indent_level)
    previous_value_type = None
    if len(keys_array) == 0:
        indent_level = PopIndent(indent_level)
    else:
        if not has_sorted_keys:
            dictionary_string += '\t'
        for key in keys_array:
            if has_sorted_keys:
                current_value_type = str(self.value[key]['isa'])
                if previous_value_type != current_value_type:
                    if previous_value_type != None:
                        dictionary_string += '/* End '+previous_value_type+' section */'
                        dictionary_string += WriteNewline(indent_level, False)
                    previous_value_type = current_value_type
                    dictionary_string += '\n/* Begin '+current_value_type+' section */'
                    dictionary_string += WriteNewline(indent_level)
                else:
                    dictionary_string += WriteIndent(indent_level)
            write_string, indent_level = key.writeString(indent_level, pretty)
            dictionary_string += write_string
            dictionary_string += ' = '
            write_string, indent_level = self.value[key].writeString(indent_level, pretty)
            dictionary_string += write_string
            dictionary_string += ';'
            should_indent = True
            is_last_key = (key == keys_array[-1])
            if is_last_key:
                if has_sorted_keys:
                    dictionary_string += WriteNewline(indent_level, False)
                    dictionary_string += '/* End '+previous_value_type+' section */'
                indent_level = PopIndent(indent_level)
            else:
                if has_sorted_keys:
                    should_indent = False
            dictionary_string += WriteNewline(indent_level, should_indent)
    dictionary_string += '}'
    return (dictionary_string, indent_level)

def writeString(self, indent_level=0, pretty=True):
    array_string = ''
    array_string += '('
    array_string += WriteNewline(indent_level)
    indent_level = PushIndent(indent_level)
    values_array = list(self.value)
    if len(values_array) == 0:
        indent_level = PopIndent(indent_level)
    else:
        array_string += '\t'
        for value in values_array:
            write_string, indent_level = value.writeString(indent_level, pretty)
            array_string += write_string
            if value != values_array[-1]:
                array_string += ','
            else:
                indent_level = PopIndent(indent_level)
            array_string += WriteNewline(indent_level)
    array_string += ')'
    return (array_string, indent_level)

def writeStringRep(self, indent_level=0, pretty=True):
    qstring_string = ''
    for character in self.value:
        qstring_string += StrParse.SanitizeCharacter(character)
    return (qstring_string, indent_level)

def writeString(self, indent_level=0, pretty=True):
    qstring_string = ''
    qstring_string += '"'
    string_rep, indent_level = self.writeStringRep(indent_level, pretty)
    qstring_string += string_rep
    qstring_string += '"'
    if pretty is True:
        qstring_string += self.writeAnnotation()
    return (qstring_string, indent_level)

def pbItemResolver(obj, type_name):
    initializer = KnownTypes[type_name]
    if initializer:
        return initializer(obj, type_name)
    else: # pragma: no cover
        message = 'Unknown type "'+type_name+'" passed to pbItemResolver!'
        raise TypeError(message)

def __iter__(self):
    """
    :return:
        An iterator of child values
    """

    return iter(self._children)

def __checkFile(self, file_path):
    can_access_file = os.path.exists(file_path)
    if can_access_file is True:
        self.file_path = file_path
    return can_access_file

def write(self, file_path=None):
    if file_path is None:
        file_path = self.file_path
    serializer = PBSerializer(file_path, self.string_encoding, self.file_type)
    serializer.write(self.root)

def write(self, obj=None):
    for case in Switch(self.file_type):
        if case('ascii'):
            try:
                file_descriptor = open(self.file_path, 'w')
                self.__writeObject(file_descriptor, obj)
                file_descriptor.close()
            except IOError as exception: # pragma: no cover
                print('I/O error({0}): {1}'.format(exception.errno, exception.strerror))
            except: # pragma: no cover
                print('Unexpected error:'+str(sys.exc_info()[0]))
                raise
            break
        if case('binary'):
            import biplist
            biplist.writePlist(obj, self.file_path)
            break
        if case('xml'):
            import plistlib
            plistlib.writePlist(obj, self.file_path)
            break
        if case():
            break

def __writeObject(self, file_descriptor=None, obj=None):
    if file_descriptor is None: # pragma: no cover
        message = 'Fatal error, file descriptor is None'
        raise TypeError(message)
    if self.string_encoding is not None:
        file_descriptor.write('// !$*'+self.string_encoding+'*$!\n')
    if obj is not None:
        write_string, indent_level = obj.writeString()
        _ = indent_level
        file_descriptor.write(write_string)

def __readTest(self, requires_object=True):
    read_result = None
    # can we parse this?
    can_parse, self.index, _annotation = StrParse.IndexOfNextNonSpace(self.data, self.index)
    # we can ignore the annotation value here
    if not can_parse:
        if self.index != len(self.data):
            if requires_object is True: # pragma: no cover
                message = 'Invalid plist file!'
                raise Exception(message)
    else:
        read_result = self.__parse(requires_object)
    return read_result

def __parse(self, requires_object=True):
    parsed_item = None
    starting_character = self.data[self.index]
    for case in Switch(starting_character):
        if case('{'):
            # parse dictionary
            parsed_item = pbItem.pbItemResolver(self.__parseDict(), 'dictionary') # pylint: disable=redefined-variable-type
            break
        if case('('):
            # parse array
            parsed_item = pbItem.pbItemResolver(self.__parseArray(), 'array') # pylint: disable=redefined-variable-type
            break
        if case('<'):
            # parse data
            parsed_item = pbItem.pbItemResolver(self.__parseData(), 'data') # pylint: disable=redefined-variable-type
            break
        if case('\''):
            pass
        if case('\"'):
            # parse quoted string
            parsed_item = pbItem.pbItemResolver(self.__parseQuotedString(), 'qstring') # pylint: disable=redefined-variable-type
            break
        if case():
            if StrParse.IsValidUnquotedStringCharacter(starting_character) is True:
                # parse unquoted string
                parsed_item = pbItem.pbItemResolver(self.__parseUnquotedString(), 'string') # pylint: disable=redefined-variable-type
            else:
                if requires_object is True: # pragma: no cover
                    message = 'Unexpected character "0x%s" at line %i of file %s' % (str(format(ord(starting_character), 'x')), StrParse.LineNumberForIndex(self.data, self.index), self.file_path)
                    raise Exception(message)
    return parsed_item

def __parseUnquotedString(self):
    string_length = len(self.data)
    start_index = self.index
    while self.index < string_length:
        current_char = self.data[self.index]
        if StrParse.IsValidUnquotedStringCharacter(current_char) is True:
            self.index += 1
        else:
            break
    if start_index != self.index:
        return self.data[start_index:self.index]
    else: # pragma: no cover
        message = 'Unexpected EOF in file %s' % self.file_path
        raise Exception(message)

def __parseQuotedString(self):
    quote = self.data[self.index]
    string_length = len(self.data)
    self.index += 1 # skip over the first quote
    start_index = self.index
    while self.index < string_length:
        current_char = self.data[self.index]
        if current_char == quote:
            break
        if current_char == '\\':
            self.index += 2
        else:
            self.index += 1
    if self.index >= string_length: # pragma: no cover
        message = 'Unterminated quoted string starting on line %s in file %s' % (str(StrParse.LineNumberForIndex(self.data, start_index)), self.file_path)
        raise Exception(message)
    else:
        string_without_quotes = StrParse.UnQuotifyString(self.data, start_index, self.index)
        self.index += 1 # advance past quote character
        return string_without_quotes

def main():
    """Main func"""

    edid_csv_cache = "/tmp/pyedid-database.csv"

    try:
        registry = Registry.from_csv(edid_csv_cache)
    except FileNotFoundError:
        print("Loading registry from web...")
        registry = Registry.from_web()
        print("Done!\n")
        registry.to_csv(edid_csv_cache)

    for raw in EdidHelper.get_edids():
